function renderCommandPerformance(range='YTD'){
  const d=commandPerfData[range]||commandPerfData.YTD,svg=document.getElementById('commandPerformanceSvg');if(!svg)return;
  const W=920,H=300,L=46,R=24,T=20,B=38;const vals=[...d.p,...d.b];let min=Math.min(...vals),max=Math.max(...vals);const pad=Math.max((max-min)*.18,1);min-=pad;max+=pad;
  const x=i=>L+(W-L-R)*(d.labels.length===1?0:i/(d.labels.length-1)),y=v=>T+(H-T-B)*(1-(v-min)/(max-min));
  const path=a=>a.map((v,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+y(v).toFixed(1)).join(' '),area=`M ${x(0)} ${H-B} L ${d.p.map((v,i)=>`${x(i)} ${y(v)}`).join(' L ')} L ${x(d.p.length-1)} ${H-B} Z`;
  let out=`<defs><linearGradient id="cmdLine" x1="0" x2="1"><stop offset="0%" stop-color="#2a74ff"/><stop offset="58%" stop-color="#5d5bf2"/><stop offset="100%" stop-color="#00a7b5"/></linearGradient><linearGradient id="cmdArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#376ff4" stop-opacity=".14"/><stop offset="100%" stop-color="#376ff4" stop-opacity=".008"/></linearGradient></defs>`;
  for(let i=0;i<5;i++){const yy=T+(H-T-B)*(i/4),val=max-(max-min)*(i/4);out+=`<line class="gridline" x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}"/><text class="axis" x="${L-8}" y="${yy+4}" text-anchor="end">${val.toFixed(1)}%</text>`;}
  d.labels.forEach((lab,i)=>{if(i===0||i===d.labels.length-1||d.labels.length<=5||i%Math.ceil(d.labels.length/5)===0)out+=`<text class="axis" x="${x(i)}" y="${H-10}" text-anchor="${i===0?'start':i===d.labels.length-1?'end':'middle'}">${lab}</text>`});
  out+=`<path class="area" d="${area}"/><path class="benchmark-line" d="${path(d.b)}"/><path class="portfolio-glow" d="${path(d.p)}"/><path class="portfolio-line" d="${path(d.p)}"/><circle class="end-dot" cx="${x(d.p.length-1)}" cy="${y(d.p[d.p.length-1])}" r="3.7"/><g id="commandFocus" style="display:none"><line class="focus" y1="${T}" y2="${H-B}"/><circle class="dot" r="4"/></g><rect class="hit" id="commandChartHit" x="${L}" y="${T}" width="${W-L-R}" height="${H-T-B}"/>`;
  svg.innerHTML=out;document.getElementById('commandCompositeValue').textContent=d.pv;document.getElementById('commandBenchmarkValue').textContent=d.bv;document.getElementById('commandActiveValue').textContent=d.av;
  const hit=svg.querySelector('#commandChartHit'),focus=svg.querySelector('#commandFocus'),tip=document.getElementById('commandChartTip');
  const pointer=ev=>{const rect=svg.getBoundingClientRect(),px=(ev.clientX-rect.left)*W/rect.width;let i=Math.round((px-L)/(W-L-R)*(d.labels.length-1));i=Math.max(0,Math.min(d.labels.length-1,i));const xx=x(i),yy=y(d.p[i]);focus.style.display='block';const line=focus.querySelector('line'),dot=focus.querySelector('circle');line.setAttribute('x1',xx);line.setAttribute('x2',xx);dot.setAttribute('cx',xx);dot.setAttribute('cy',yy);tip.style.display='block';tip.innerHTML=`<strong>${d.labels[i]}</strong><br>Composite ${d.p[i].toFixed(2)}% · Benchmark ${d.b[i].toFixed(2)}%`;tip.style.left=Math.min(rect.width-190,Math.max(4,(ev.clientX-rect.left)+10))+'px';tip.style.top=Math.max(6,(ev.clientY-rect.top)-46)+'px';};
  hit.addEventListener('pointermove',pointer);hit.addEventListener('pointerdown',pointer);hit.addEventListener('pointerleave',()=>{focus.style.display='none';tip.style.display='none'});
}

