let selectedResearchTicker='DLTA.ZW';const researchNotes={};
function renderResearchList(){const host=document.getElementById('equityResearchList');if(!host)return;const q=(document.getElementById('equityResearchSearch')?.value||'').toLowerCase(),filter=document.querySelector('[data-research-market].active')?.dataset.researchMarket||'all';host.innerHTML=Object.entries(equityResearchData).filter(([k,v])=>(filter==='all'||v.market===filter)&&`${k} ${v.name} ${v.sector}`.toLowerCase().includes(q)).map(([k,v])=>`<button type="button" data-equity-ticker="${k}" class="${k===selectedResearchTicker?'active':''}"><span class="ra">${v.avatar}</span><span><strong>${k.replace('.ZW','').replace('.VX','')}</strong><small>${v.name}</small></span><em>${v.recommendation}</em></button>`).join('')||'<div class="research-chart-empty-v7" style="position:static;min-height:120px">No securities match this filter.</div>';host.querySelectorAll('[data-equity-ticker]').forEach(b=>b.addEventListener('click',()=>selectResearchSecurity(b.dataset.equityTicker)));}
function researchSeriesFor(ticker){const key=ticker.startsWith('DLTA')?'DLTA':ticker.startsWith('CBZ')?'CBZ':null;return key&&typeof marketUniverse!=='undefined'&&marketUniverse[key]?marketUniverse[key].series:null;}
function renderResearchPriceChart(ticker){const svg=document.getElementById('researchPriceChart'),empty=document.getElementById('researchPriceChartEmpty'),series=researchSeriesFor(ticker);if(!svg||!empty)return;if(!series||series.length<2){svg.innerHTML='';empty.hidden=false;return;}empty.hidden=true;const data=series,W=760,H=270,L=38,R=44,T=16,B=32,vals=data.map(d=>d[1]),min0=Math.min(...vals),max0=Math.max(...vals),pad=Math.max((max0-min0)*.18,.12),min=min0-pad,max=max0+pad,x=i=>L+(W-L-R)*i/(data.length-1),y=v=>T+(H-T-B)*(1-(v-min)/(max-min)),path=data.map((d,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+y(d[1]).toFixed(1)).join(' '),area=`M ${x(0)} ${H-B} L ${data.map((d,i)=>`${x(i)} ${y(d[1])}`).join(' L ')} L ${x(data.length-1)} ${H-B} Z`;let out='<defs><linearGradient id="researchLineGradient" x1="0" x2="1"><stop offset="0%" stop-color="#236fff"/><stop offset="70%" stop-color="#5f59f2"/><stop offset="100%" stop-color="#00a7b5"/></linearGradient><linearGradient id="researchAreaGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#2c6df4" stop-opacity=".12"/><stop offset="100%" stop-color="#2c6df4" stop-opacity="0"/></linearGradient></defs>';for(let i=0;i<4;i++){const yy=T+(H-T-B)*i/3,outv=max-(max-min)*i/3;out+=`<line class="grid" x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}"/><text class="axis" x="${W-R+6}" y="${yy+4}">${outv.toFixed(2)}</text>`}out+=`<path class="area" d="${area}"/><path class="line-glow" d="${path}"/><path class="line" d="${path}"/><circle class="end-dot" cx="${x(data.length-1)}" cy="${y(data[data.length-1][1])}" r="3.4"/><text class="axis" x="${L}" y="${H-8}">${data[0][0]}</text><text class="axis" x="${W-R}" y="${H-8}" text-anchor="end">${data[data.length-1][0]}</text>`;svg.innerHTML=out;}
function renderResearchFinancials(d){const host=document.getElementById('researchFinancialTable');if(host)host.innerHTML=`<table><thead><tr><th>Measure</th><th>Reported value</th><th>Context</th></tr></thead><tbody>${d.financials.map(r=>`<tr><td><strong>${r[0]}</strong></td><td>${r[1]}</td><td>${r[2]}</td></tr>`).join('')}</tbody></table>`;const rt=document.getElementById('researchReadThrough');if(rt)rt.innerHTML=d.readThrough.map(x=>`<div><strong>Analyst read-through</strong><span>${x}</span></div>`).join('');}
function renderResearchDocs(d){const host=document.getElementById('researchDocumentList');if(!host)return;host.innerHTML=d.docs.map((doc,i)=>`<button type="button" data-doc-index="${i}"><span><strong>${doc.title}</strong><small>${doc.source}</small></span><em>${doc.date}</em></button>`).join('');host.querySelectorAll('[data-doc-index]').forEach(b=>b.addEventListener('click',()=>{host.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));const doc=d.docs[+b.dataset.docIndex];document.getElementById('researchDocumentTitle').textContent=doc.title;document.getElementById('researchDocumentPreview').innerHTML=`<h4>${doc.title}</h4><p>${doc.summary}</p><p><strong>Source:</strong> ${doc.source}<br><strong>Published / period:</strong> ${doc.date}</p><p>This in-product extract is an analyst reading aid. The controlled source document remains attached to the evidence record in production.</p>`;}));host.querySelector('button')?.click();}
function updateValuationPreview(d){const target=Number(document.getElementById('modelTargetPrice')?.value||d.model.target)||0;const fmt=v=>d.price.includes('ZWG cents')?`${v.toFixed(2)} ZWG cents`:d.price.startsWith('ZWG')?`ZWG ${v.toFixed(2)}`:v.toFixed(2);document.getElementById('valuationBear').textContent=fmt(target*.82);document.getElementById('valuationBase').textContent=fmt(target);document.getElementById('valuationBull').textContent=fmt(target*1.18);}
function selectResearchSecurity(ticker){if(!equityResearchData[ticker])return;selectedResearchTicker=ticker;const d=equityResearchData[ticker];const set=(id,val)=>{const e=document.getElementById(id);if(e)e.textContent=val};set('researchAvatar',d.avatar);set('researchCompanyName',d.name);set('researchTicker',ticker);set('researchSector',d.sector);set('researchExchange',d.exchange);set('researchSpotPrice',d.price);set('researchSpotChange',d.change);set('researchSpotAsOf',d.asOf);set('researchRecommendation',d.recommendation);set('researchThesisText',d.thesis);set('researchTarget',d.target);set('researchUpside',d.upside);set('researchConviction',d.conviction);set('researchFinancialPeriod',d.period);document.getElementById('researchSpotChange').className=d.change.includes('−')?'market-down':'market-up';document.getElementById('researchFactGrid').innerHTML=d.facts.map(f=>`<div><span>${f[0]}</span><strong>${f[1]}</strong><small>${f[2]}</small></div>`).join('');renderResearchPriceChart(ticker);renderResearchFinancials(d);renderResearchDocs(d);const m=d.model;document.getElementById('modelRevenueGrowth').value=m.growth;document.getElementById('modelMargin').value=m.margin;document.getElementById('modelDiscountRate').value=m.discount;document.getElementById('modelTargetPrice').value=m.target;document.getElementById('modelRecommendation').value=m.recommendation;document.getElementById('modelConviction').value=m.conviction;document.getElementById('researchAnalystNote').value=researchNotes[ticker]||'';document.getElementById('researchNoteHistory').innerHTML=researchNotes[ticker]?`<div><strong>Current session note</strong><span>${researchNotes[ticker]}</span><small>Saved in prototype session</small></div>`:'<div><strong>No session notes yet</strong><span>Use the analyst journal to capture a working view.</span></div>';updateValuationPreview(d);renderResearchList();}

function runRiskScenario(){const eq=Number(document.getElementById('riskEquityShock')?.value||0),fx=Number(document.getElementById('riskFxShock')?.value||0),rates=Number(document.getElementById('riskRateShock')?.value||0),red=Number(document.getElementById('riskRedemptionShock')?.value||0);const loss=eq*.28+fx*.10-Math.abs(rates)*.007;const cover=Math.max(.25,1.84-red*.035);const cash=7.12-(84.62*red/100)+1.10;const stateTxt=cover<1.25||loss<-10?'Escalate':cover<1.5||loss<-7?'Review':'Within';const reason=cover<1.25?'Liquidity below 1.25× floor':loss<-10?'Stress loss above 10% tolerance':cover<1.5?'Liquidity near floor':loss<-7?'Stress loss requires review':'Inside current risk appetite';const lossText=(loss>=0?'+':'−')+Math.abs(loss).toFixed(2)+'%';document.getElementById('riskScenarioLoss').textContent=lossText;document.getElementById('riskHeadlineStress').textContent=lossText;document.getElementById('riskScenarioLiquidity').textContent=cover.toFixed(2)+'×';document.getElementById('riskHeadlineLiquidity').textContent=cover.toFixed(2)+'×';document.getElementById('riskScenarioCash').textContent=(cash>=0?'US$ ':'−US$ ')+Math.abs(cash).toFixed(2)+'M';document.getElementById('riskScenarioState').textContent=stateTxt;document.getElementById('riskScenarioState').className=stateTxt==='Within'?'positive-text':'attention-text';document.getElementById('riskScenarioReason').textContent=reason;return {lossText,cover,cash,stateTxt};}
function addRiskLimit(){const metric=document.getElementById('riskLimitMetric').value,scope=document.getElementById('riskLimitScope').value,thr=Number(document.getElementById('riskLimitThreshold').value),unit=document.getElementById('riskLimitUnit').value,action=document.getElementById('riskLimitAction').value;if(!Number.isFinite(thr)||thr<=0)return toast('Invalid threshold','Enter a positive limit threshold.','error');const tr=document.createElement('tr');tr.innerHTML=`<td><strong>${metric}</strong><small>${scope}</small></td><td>—</td><td>—</td><td>${thr.toFixed(2)} ${unit}</td><td>Pending data</td><td>${action}</td><td><span class="outline-status blue">Draft</span></td>`;document.getElementById('riskLimitRows').appendChild(tr);toast('Draft limit added',`${metric} · ${thr.toFixed(2)} ${unit} requires independent approval before it becomes effective.`);}

function renderQuickSparkline(){const svg=document.getElementById('quickOrderSparkline');if(!svg||typeof marketUniverse==='undefined')return;const item=marketUniverse[activeMarketSecurity],data=item?.series?.slice(-5)||[];if(data.length<2){svg.innerHTML='';return;}const W=360,H=70,L=2,R=2,T=6,B=7,vals=data.map(d=>d[1]),min0=Math.min(...vals),max0=Math.max(...vals),pad=Math.max((max0-min0)*.2,.05),min=min0-pad,max=max0+pad,x=i=>L+(W-L-R)*i/(data.length-1),y=v=>T+(H-T-B)*(1-(v-min)/(max-min)),path=data.map((d,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+y(d[1]).toFixed(1)).join(' '),area=`M ${x(0)} ${H-B} L ${data.map((d,i)=>`${x(i)} ${y(d[1])}`).join(' L ')} L ${x(data.length-1)} ${H-B} Z`;svg.innerHTML=`<defs><linearGradient id="quickSparkGradient" x1="0" x2="1"><stop offset="0%" stop-color="#286fff"/><stop offset="100%" stop-color="#00a8b6"/></linearGradient><linearGradient id="quickSparkArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#2d6ff6" stop-opacity=".12"/><stop offset="100%" stop-color="#2d6ff6" stop-opacity="0"/></linearGradient></defs><path class="spark-area" d="${area}"/><path class="spark-line" d="${path}"/>`;const delta=(data[data.length-1][1]/data[0][1]-1)*100;const ch=document.getElementById('quickOrderChange');if(ch){ch.textContent=(delta>=0?'+':'−')+Math.abs(delta).toFixed(2)+'%';ch.className=delta>=0?'market-up':'market-down';}}
const baseSelectMarketSecurity=selectMarketSecurity;selectMarketSecurity=function(key){if(!document.getElementById('marketSecurityAvatar'))return;baseSelectMarketSecurity(key);const sel=document.getElementById('quickSecuritySelect');if(sel)sel.value=key;renderQuickSparkline();const i=marketUniverse[key];if(i){const isDelta=i.orderTicker==='DLTA.ZW';document.getElementById('marketResearchView').textContent=isDelta?'Accumulate · A− conviction':i.orderTicker==='CBZ.ZW'?'Hold · B+ conviction':'Research available';document.getElementById('marketResearchSummary').textContent=isDelta?'Volume and margin resilience remain supportive; issuer concentration is the binding control.':'Latest public filings and internal analyst model are available in Research & IC.';document.getElementById('marketPositionValue').textContent=isDelta?'9.10% NAV':'Position context available in IBOR';document.getElementById('marketIssuerHeadroom').textContent=isDelta?'0.90%':'See risk book';}}
const baseRenderMarketChart=renderMarketChart;renderMarketChart=function(){const svg=document.getElementById('marketPriceChart'),wrap=document.getElementById('marketChartWrap'),tip=document.getElementById('marketChartTooltip');if(!svg||!wrap||!tip)return;const item=marketUniverse[activeMarketSecurity],data=marketRangeData(item),W=900,H=310,L=44,R=54,T=16,priceBottom=224,volTop=242,volBottom=276,prices=data.map(d=>d[1]),vols=data.map(d=>d[2]),min0=Math.min(...prices),max0=Math.max(...prices),pad=Math.max((max0-min0)*.18,.1),min=min0-pad,max=max0+pad,vmax=Math.max(...vols,1),x=i=>L+(W-L-R)*(data.length===1?0:i/(data.length-1)),y=v=>T+(priceBottom-T)*(1-(v-min)/(max-min)),vy=v=>volBottom-(volBottom-volTop)*(v/vmax),pts=data.map((d,i)=>`${x(i).toFixed(1)},${y(d[1]).toFixed(1)}`).join(' '),area=`M ${x(0)} ${priceBottom} L ${data.map((d,i)=>`${x(i)} ${y(d[1])}`).join(' L ')} L ${x(data.length-1)} ${priceBottom} Z`;let out='<defs><linearGradient id="marketLineGradient" x1="0" x2="1"><stop offset="0%" stop-color="#2a73ff"/><stop offset="72%" stop-color="#6357f2"/><stop offset="100%" stop-color="#00a7b5"/></linearGradient><linearGradient id="marketAreaGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#286ef3" stop-opacity=".11"/><stop offset="100%" stop-color="#286ef3" stop-opacity="0"/></linearGradient></defs>';for(let n=0;n<5;n++){const val=max-(max-min)*n/4,yy=y(val);out+=`<line class="grid" x1="${L}" y1="${yy}" x2="${W-R}" y2="${yy}"/><text class="axis-text" x="${W-R+7}" y="${yy+4}">${val.toFixed(2)}</text>`}const labs=[0,Math.floor((data.length-1)/2),data.length-1];labs.forEach(i=>out+=`<text class="axis-text" x="${x(i)}" y="${H-9}" text-anchor="${i===0?'start':i===data.length-1?'end':'middle'}">${data[i][0]}</text>`);const bw=Math.max(2,(W-L-R)/data.length*.42);data.forEach((d,i)=>{const yy=vy(d[2]);out+=`<rect class="volume-bar" x="${x(i)-bw/2}" y="${yy}" width="${bw}" height="${volBottom-yy}" rx="1"/>`});out+=`<path class="price-area" d="${area}"/><polyline class="price-glow" points="${pts}"/><polyline class="price-line" style="stroke:url(#marketLineGradient)" points="${pts}"/><circle class="end-dot" cx="${x(data.length-1)}" cy="${y(data[data.length-1][1])}" r="3.5"/><g id="marketFocus" style="display:none"><line class="focus-line" x1="0" y1="${T}" x2="0" y2="${volBottom}"/><circle class="focus-dot" cx="0" cy="0" r="4"/></g><rect id="marketHit" x="${L}" y="${T}" width="${W-L-R}" height="${volBottom-T}" fill="transparent" style="cursor:crosshair"/>`;svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.innerHTML=out;const hit=svg.querySelector('#marketHit'),focus=svg.querySelector('#marketFocus');const pointer=ev=>{const rect=svg.getBoundingClientRect(),px=(ev.clientX-rect.left)*W/rect.width;let idx=Math.round((px-L)/(W-L-R)*(data.length-1));idx=Math.max(0,Math.min(data.length-1,idx));const d=data[idx],xx=x(idx),yy=y(d[1]);focus.style.display='block';focus.querySelector('line').setAttribute('x1',xx);focus.querySelector('line').setAttribute('x2',xx);focus.querySelector('circle').setAttribute('cx',xx);focus.querySelector('circle').setAttribute('cy',yy);tip.style.display='block';tip.innerHTML=`<strong>${d[0]} · ${item.currency} ${d[1].toFixed(2)}</strong><small>Volume ${Number(d[2]).toLocaleString()}</small>`;tip.style.left=Math.min(rect.width-150,Math.max(4,(ev.clientX-rect.left)+10))+'px';tip.style.top=Math.max(8,(ev.clientY-rect.top)-42)+'px';};hit.addEventListener('pointermove',pointer);hit.addEventListener('pointerdown',pointer);hit.addEventListener('pointerleave',()=>{focus.style.display='none';tip.style.display='none'});document.getElementById('marketPeriodHigh').textContent=`${item.currency} ${Math.max(...prices).toFixed(2)}`;document.getElementById('marketPeriodLow').textContent=`${item.currency} ${Math.min(...prices).toFixed(2)}`;renderQuickSparkline();};
const baseRecalcQuickOrder=recalcQuickOrder;recalcQuickOrder=function(){if(!document.getElementById('quickOrderAmount'))return;baseRecalcQuickOrder();const i=marketUniverse[activeMarketSecurity];if(!i)return;const amount=Number(document.getElementById('quickOrderAmount')?.value||0),type=document.getElementById('quickOrderType')?.value||'Limit',limit=Number(document.getElementById('quickLimitPrice')?.value||i.last),price=type==='Market'?i.last:limit,qty=quickUnit==='shares'?amount:(price>0?amount/price:0),consideration=Math.max(0,qty*price),availableCash=i.currency==='ZWG'?32650000:1926000,availableShares=i.orderTicker==='DLTA.ZW'?1142000:i.orderTicker==='CBZ.ZW'?400000:0,box=document.getElementById('quickOrderValidation'),review=document.getElementById('loadInstitutionalTicket');let error='';if(!Number.isFinite(amount)||amount<=0)error='Enter an order size greater than zero.';else if(!Number.isFinite(price)||price<=0)error='Enter a valid positive price.';else if(quickSide==='Buy'&&consideration>availableCash)error='Order exceeds currently available cash before fees.';else if(quickSide==='Sell'&&qty>availableShares)error='Sell quantity exceeds the available-to-sell position in this prototype.';if(box){box.classList.toggle('error',!!error);box.innerHTML=error?`<span>Review required</span><small>${error}</small>`:`<span>Ready for institutional review</span><small>Order size is valid. Final submission still re-runs cash, mandate, liquidity and counterparty controls.</small>`}if(review)review.disabled=!!error;const av=document.getElementById('quickOrderAvailable'),lab=document.getElementById('quickOrderAvailableLabel');if(av&&lab){if(quickSide==='Buy'){lab.textContent='Available cash';av.textContent=compactMoney(availableCash,i.currency)}else{lab.textContent='Available to sell';av.textContent=Math.floor(availableShares).toLocaleString()+' shares'}}const exposure=document.getElementById('quickOrderExposure');if(exposure)exposure.textContent=i.orderTicker==='DLTA.ZW'?(9.10+(qty/250000)*.62*(quickSide==='Buy'?1:-1)).toFixed(2)+'%':'See risk book';const qtyLabel=document.getElementById('quickQtyLabelText');if(qtyLabel)qtyLabel.textContent=quickUnit==='shares'?'Number of shares':`Order value (${i.currency})`;renderQuickSparkline();};
const baseOpenMarketSecurityView=openMarketSecurityView;openMarketSecurityView=function(view,button){if(view==='research'){const i=marketUniverse[activeMarketSecurity];selectedResearchTicker=i.orderTicker;navigate('research');setTimeout(()=>selectResearchSecurity(selectedResearchTicker),0);return;}return baseOpenMarketSecurityView(view,button);};

function openRiskCaseIntake(){
  openDrawer({eyebrow:'RISK / COMPLIANCE INTAKE',title:'New control case',subtitle:'Capture the issue, owner, due date and evidence before it enters the governed case queue.',body:`<form id="riskCaseIntakeForm" class="risk-case-form-v7"><label>Case type<select id="riskCaseType"><option>Mandate exception</option><option>AML / source of funds</option><option>Market risk</option><option>Liquidity risk</option><option>Operational risk</option><option>Counterparty risk</option></select></label><label>Severity<select id="riskCaseSeverity"><option>Medium</option><option>High</option><option>Critical</option><option>Low</option></select></label><label>Portfolio / client<input id="riskCaseSubject" value="Balanced Growth Fund"/></label><label>Owner<select id="riskCaseOwner"><option>Risk</option><option>Compliance</option><option>Investment Director</option><option>Operations</option></select></label><label>Due date<input id="riskCaseDue" type="date" value="2026-08-29"/></label><label>Reference<input id="riskCaseReference" placeholder="Order, client, security or control ID"/></label><label class="wide">Issue description<textarea id="riskCaseDescription" placeholder="Describe the trigger, observed exposure, evidence and decision required..."></textarea></label><label class="wide">Evidence / source note<textarea id="riskCaseEvidence" placeholder="Record source system, filing, custodian statement, screening result or document reference..."></textarea></label><div class="form-actions wide"><button type="button" class="btn secondary" id="riskCaseSaveDraft">Save draft</button><button type="submit" class="btn primary">Create controlled case</button></div></form>`});
  const f=document.getElementById('riskCaseIntakeForm');if(!f)return;document.getElementById('riskCaseSaveDraft')?.addEventListener('click',()=>toast('Risk case draft saved','The intake fields were checkpointed as a draft control record.'));f.addEventListener('submit',e=>{e.preventDefault();const desc=document.getElementById('riskCaseDescription').value.trim();if(!desc)return toast('Description required','Record the issue before creating a controlled case.','error');const type=document.getElementById('riskCaseType').value,sev=document.getElementById('riskCaseSeverity').value,subject=document.getElementById('riskCaseSubject').value.trim()||'Unspecified subject';closeDrawer();toast('Controlled risk case created',`${type} · ${subject} · ${sev} severity was added to the review queue.`);});
}

