  renderCommandPerformance('YTD');document.querySelectorAll('[data-command-range]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-command-range]').forEach(x=>x.classList.toggle('active',x===b));renderCommandPerformance(b.dataset.commandRange)}));
