function escapeHtmlV8(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function renderRoleSwitcherV8(){const sw=document.getElementById('roleSwitcher');if(!sw)return;const value=state.role;sw.innerHTML=Object.entries(roleLabels).map(([k,v])=>`<option value="${k}">${escapeHtmlV8(v)}</option>`).join('');if(roleLabels[value])sw.value=value;else{state.role='investment_director';sw.value=state.role}}
function renderRbacMatrix(){const table=document.getElementById('rbacMatrix');if(!table)return;const roles=Object.keys(roleLabels).filter(r=>r!=='system_admin');const head=table.querySelector('thead'),body=table.querySelector('tbody');head.innerHTML=`<tr><th>Capability</th>${roles.map(r=>`<th title="${escapeHtmlV8(roleLabels[r])}">${escapeHtmlV8(roleLabels[r].replace('Investment ','Inv. ').replace('Portfolio ','Portfolio ').replace('Fund Accountant','Fund Acct.').replace('Client Services','Client Svc.'))}</th>`).join('')}</tr>`;body.innerHTML=permissionCatalogV8.map(([group,code,label])=>`<tr><td><strong>${escapeHtmlV8(label)}</strong><small>${escapeHtmlV8(group)} · ${code}</small></td>${roles.map(r=>`<td><button type="button" class="perm-toggle ${(rolePermissions[r]||[]).includes(code)?'on':''}" data-permission-code="${code}" data-role="${r}" aria-label="${escapeHtmlV8(label)} for ${escapeHtmlV8(roleLabels[r])}"></button></td>`).join('')}</tr>`).join('');body.querySelectorAll('.perm-toggle').forEach(b=>b.addEventListener('click',()=>togglePermissionV8(b.dataset.role,b.dataset.permissionCode,b)))}
function togglePermissionV8(role,code,button){if(role==='system_admin')return toast('Protected role','System Administrator privileges are platform-only and cannot be extended through the transaction matrix.','warn');const arr=rolePermissions[role]||(rolePermissions[role]=[]);const i=arr.indexOf(code);if(i>=0)arr.splice(i,1);else arr.push(code);button?.classList.toggle('on',i<0);localSaveRbacV8();applyRBAC(false);renderSodV8();toast('Permission updated',`${roleLabels[role]} ${i>=0?'no longer has':'now has'} ${code}.`)}
function renderRbacUsersV8(){const body=document.getElementById('rbacUserRows');if(!body)return;const opts=Object.entries(roleLabels).map(([k,v])=>`<option value="${k}">${escapeHtmlV8(v)}</option>`).join('');body.innerHTML=rbacUsersV8.map((u,i)=>`<tr><td><strong>${escapeHtmlV8(u.name)}</strong><small>${escapeHtmlV8(u.email)}</small></td><td><select data-rbac-user="${i}" ${u.role==='system_admin'?'aria-label="Protected platform administrator role"':''}>${opts}</select></td><td><span class="outline-status ${u.access==='Active'?'green':u.access==='Privileged'?'blue':'amber'}">${escapeHtmlV8(u.access)}</span></td><td>${escapeHtmlV8(u.last)}</td><td><button class="row-action" type="button" data-preview-user="${i}">Preview</button></td></tr>`).join('');body.querySelectorAll('[data-rbac-user]').forEach(sel=>{const i=+sel.dataset.rbacUser;sel.value=rbacUsersV8[i].role;sel.addEventListener('change',()=>assignUserRoleV8(i,sel.value))});body.querySelectorAll('[data-preview-user]').forEach(b=>b.addEventListener('click',()=>previewUserV8(+b.dataset.previewUser)));document.getElementById('rbacUserCount')&&(document.getElementById('rbacUserCount').textContent=rbacUsersV8.length);document.getElementById('rbacRoleCount')&&(document.getElementById('rbacRoleCount').textContent=Object.keys(roleLabels).length)}
