function renderSodV8(){const host=document.getElementById('sodDynamicList');if(!host)return 0;const findings=[];if(accessPolicyV8.orderApproval!=='independent')findings.push(['!','Order maker-checker relaxed','Order approval is not set to independent checker.','Policy review']);if(accessPolicyV8.cashApproval!=='independent')findings.push(['!','Cash maker-checker relaxed','Cash journal approval is not fully independent.','Policy review']);const admins=rbacUsersV8.filter(u=>u.role==='system_admin');if(admins.length>2)findings.push(['!','Privileged account count',`${admins.length} System Administrators are assigned.`,'Review privileged access']);const protectedMoney=['orders.create','orders.approve','orders.route','cash.journal.create','cash.journal.approve','cash.close'];const adminMoney=protectedMoney.filter(p=>(rolePermissions.system_admin||[]).includes(p));if(adminMoney.length)findings.push(['!','Platform admin monetary privilege',adminMoney.join(', '),'Remove immediately']);if(!findings.length)findings.push(['✓','No blocking SoD conflicts','Independent approval policies are active and platform administrators have no monetary permissions.','Controlled']);host.innerHTML=findings.map((f,i)=>`<div class="${f[0]==='!'?'sod-alert':''}"><span>${f[0]}</span><div><strong>${escapeHtmlV8(f[1])}</strong><small>${escapeHtmlV8(f[2])}</small><b>${escapeHtmlV8(f[3])}</b></div></div>`).join('');const count=findings.filter(f=>f[0]==='!').length;document.getElementById('rbacConflictCount')&&(document.getElementById('rbacConflictCount').textContent=count);document.getElementById('rbacConflictSub')&&(document.getElementById('rbacConflictSub').textContent=count?`${count} finding${count===1?'':'s'} require review`:'No blocking conflicts');return count}
