function currentScenarioTargetsV8(){return [...document.querySelectorAll('[data-scenario-target]')].map(i=>Number(i.value)||0)}
function recalcScenarioTargetsV8(){const inputs=[...document.querySelectorAll('[data-scenario-target]')],total=inputs.reduce((a,i)=>a+(Number(i.value)||0),0);inputs.forEach(i=>{const cur=Number(i.dataset.current)||0,d=(Number(i.value)||0)-cur,em=document.querySelector(`[data-scenario-delta="${CSS.escape(i.dataset.scenarioTarget)}"]`);if(em){em.textContent=`${d>=0?'+':''}${d.toFixed(1)}%`;em.classList.toggle('positive-text',d>0);em.classList.toggle('attention',d<0)}});const t=document.getElementById('scenarioTargetTotal'),st=document.getElementById('scenarioTargetStatus');if(t)t.textContent=total.toFixed(1)+'%';if(st){const ok=Math.abs(total-100)<.051;st.textContent=ok?'Valid allocation':`${(100-total).toFixed(1)}% ${total<100?'unallocated':'over-allocated'}`;st.classList.toggle('error',!ok)}return total}
function normalizeScenarioTargetsV8(){const ins=[...document.querySelectorAll('[data-scenario-target]')],sum=ins.reduce((a,i)=>a+(Number(i.value)||0),0);if(sum<=0)return;let used=0;ins.forEach((i,n)=>{let v=n===ins.length-1?100-used:Math.round((Number(i.value)||0)/sum*1000)/10;used+=v;i.value=v.toFixed(1)});recalcScenarioTargetsV8()}
