function loadScenarioV8(id,notify=true){const sc=portfolioScenariosV8.find(x=>x.id===id);if(!sc)return;activeScenarioIdV8=id;const set=(id,v)=>{const e=document.getElementById(id);if(e)e.value=v};set('scenarioPortfolioSelect',sc.portfolio);set('scenarioObjectiveSelect',sc.objective);set('scenarioTeInput',sc.te);set('scenarioCashInput',sc.cash);set('scenarioTurnoverInput',sc.turnover);document.querySelectorAll('[data-scenario-target]').forEach((i,n)=>{if(sc.targets[n]!=null)i.value=sc.targets[n]});const ctxP=document.getElementById('scenarioContextPortfolio'),ctxM=document.getElementById('scenarioContextModel'),ctxO=document.getElementById('scenarioContextObjective');if(ctxP)ctxP.textContent=sc.portfolio;if(ctxM)ctxM.textContent=sc.name.replace(/^Scenario \d+ · /,'')+' · saved '+sc.saved;if(ctxO)ctxO.textContent=`${document.getElementById('scenarioObjectiveSelect')?.selectedOptions[0]?.text||'Objective'} / ${sc.te}% TE`;document.querySelectorAll('[data-scenario]').forEach(b=>b.classList.toggle('active',b.dataset.scenario===sc.style));recalcScenarioTargetsV8();if(notify)toast('Scenario loaded',`${sc.name} loaded into the construction workspace.`)}
function saveActiveScenarioV8(){const sc=portfolioScenariosV8.find(x=>x.id===activeScenarioIdV8);if(!sc)return;const total=recalcScenarioTargetsV8();if(Math.abs(total-100)>.051)return toast('Target weights must equal 100%',`Current target total is ${total.toFixed(1)}%. Normalise or edit the allocation before saving.`,'error');sc.portfolio=document.getElementById('scenarioPortfolioSelect').value;sc.objective=document.getElementById('scenarioObjectiveSelect').value;sc.te=Number(document.getElementById('scenarioTeInput').value);sc.cash=Number(document.getElementById('scenarioCashInput').value);sc.turnover=Number(document.getElementById('scenarioTurnoverInput').value);sc.targets=currentScenarioTargetsV8();sc.style=document.querySelector('[data-scenario].active')?.dataset.scenario||sc.style;sc.saved=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});localSaveScenariosV8();loadScenarioV8(sc.id,false);toast('Scenario saved',`${sc.name} checkpointed with its targets, constraints and objective.`)}
function openScenarioHowToV8(){openDrawer({eyebrow:'PORTFOLIO CONSTRUCTION · WORKFLOW GUIDE',title:'How to create a scenario',subtitle:'A scenario is a controlled what-if portfolio, not an executable order.',body:`<section class="detail-section"><h3>1 · Choose the portfolio</h3><p>Select the portfolio whose live IBOR positions form the starting point.</p></section><section class="detail-section"><h3>2 · Define the objective</h3><p>Choose whether you want to maximise active return, minimise risk, improve liquidity or increase income. Set tracking-error, cash and turnover guardrails.</p></section><section class="detail-section"><h3>3 · Edit target weights</h3><p>Change the target allocation cells. The workspace recalculates deltas immediately and requires the total to equal 100%.</p></section><section class="detail-section"><h3>4 · Run optimisation</h3><p>The prototype evaluates the selected style against the active constraints and produces expected return, tracking error, turnover and estimated transaction cost.</p></section><section class="detail-section"><h3>5 · Compare and save</h3><p>Save alternatives, compare their outputs, then retain the chosen scenario as the controlled decision record.</p></section><section class="detail-section"><h3>6 · Raise proposed orders</h3><p>Only the chosen scenario is promoted to Order Management. Every generated instruction still runs cash, mandate, liquidity, counterparty and maker-checker controls.</p></section>`})}
function openNewScenarioV8(){openDrawer({eyebrow:'PORTFOLIO CONSTRUCTION · NEW SCENARIO',title:'Create scenario',subtitle:'Create a new what-if branch from the current portfolio state.',body:`<form id="newScenarioFormV8"><section class="detail-section"><div class="detail-grid"><label class="detail-field"><span>Scenario name</span><input id="newScenarioNameV8" value="New rebalance" required></label><label class="detail-field"><span>Portfolio</span><select id="newScenarioPortfolioV8">${portfolios.map(p=>`<option>${escapeHtmlV8(p.name)}</option>`).join('')}</select></label><label class="detail-field"><span>Objective</span><select id="newScenarioObjectiveV8"><option value="active">Maximise active return</option><option value="risk">Minimise risk</option><option value="liquidity">Improve liquidity</option><option value="income">Maximise income</option></select></label><label class="detail-field"><span>Start from</span><select id="newScenarioBaseV8"><option value="active">Current active scenario</option><option value="current">Current portfolio weights</option></select></label></div></section><div class="form-actions"><button type="button" class="btn secondary" onclick="closeDrawer()">Cancel</button><button type="submit" class="btn primary">Create scenario</button></div></form>`});setTimeout(()=>document.getElementById('newScenarioFormV8')?.addEventListener('submit',e=>{e.preventDefault();const name=document.getElementById('newScenarioNameV8').value.trim();if(!name)return;const activeBase=portfolioScenariosV8.find(x=>x.id===activeScenarioIdV8)||portfolioScenariosV8[0],baseMode=document.getElementById('newScenarioBaseV8').value;const base=baseMode==='current'?{...JSON.parse(JSON.stringify(activeBase)),targets:[32.4,14.8,28.8,10.2,13.8],style:'balanced'}:activeBase;const id='SCN-'+String(Date.now()).slice(-5);const sc={...JSON.parse(JSON.stringify(base)),id,name,portfolio:document.getElementById('newScenarioPortfolioV8').value,objective:document.getElementById('newScenarioObjectiveV8').value,saved:'New'};portfolioScenariosV8.unshift(sc);activeScenarioIdV8=id;localSaveScenariosV8();renderScenarioLibraryV8();closeDrawer();toast('Scenario created',`${name} created as an independent what-if branch.`)}),0)}
function compareScenariosV8(){const rows=portfolioScenariosV8.slice(0,6).map(sc=>{const vals=sc.style==='defensive'?['11.9%','5.2%','6.1%','14 bps']:sc.style==='growth'?['15.1%','7.4%','10.8%','23 bps']:['13.6%','6.9%','8.7%','18 bps'];return `<tr><td><strong>${escapeHtmlV8(sc.name)}</strong><small>${escapeHtmlV8(sc.portfolio)}</small></td><td>${vals[0]}</td><td>${vals[1]} / ${sc.te.toFixed(1)}% limit</td><td>${vals[2]} / ${sc.turnover.toFixed(1)}% budget</td><td>${vals[3]}</td><td>${sc.cash.toFixed(1)}%</td><td><button type="button" class="row-action" onclick="closeDrawer();navigate('portfolio-lab');loadScenarioV8('${sc.id}')">Load</button></td></tr>`}).join('');openDrawer({eyebrow:'PORTFOLIO CONSTRUCTION · SCENARIO LIBRARY',title:'Compare scenarios',subtitle:'Compare controlled alternatives before selecting an implementation path.',body:`<section class="detail-section"><div class="table-wrap"><table><thead><tr><th>Scenario</th><th>Expected return</th><th>Tracking error</th><th>Turnover</th><th>Est. costs</th><th>Min cash</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></section>`})}
const baseRunInstitutionalOptimizerV8=runInstitutionalOptimizer;runInstitutionalOptimizer=function(){const total=recalcScenarioTargetsV8();if(Math.abs(total-100)>.051)return toast('Allocation incomplete',`Target weights total ${total.toFixed(1)}%. They must equal 100% before optimisation.`,'error');const teLimit=Number(document.getElementById('scenarioTeInput')?.value||7.5),turnoverBudget=Number(document.getElementById('scenarioTurnoverInput')?.value||12),cashMin=Number(document.getElementById('scenarioCashInput')?.value||6);baseRunInstitutionalOptimizerV8();const te=Number(String(document.getElementById('scenarioTe')?.textContent||'0').replace('%',''))||0,turn=Number(String(document.getElementById('scenarioTurnover')?.textContent||'0').replace('%',''))||0;const status=document.querySelector('.constraint-panel .outline-status');const breaches=[];if(te>teLimit)breaches.push(`tracking error ${te.toFixed(1)}% > ${teLimit.toFixed(1)}%`);if(turn>turnoverBudget)breaches.push(`turnover ${turn.toFixed(1)}% > ${turnoverBudget.toFixed(1)}%`);const targets=currentScenarioTargetsV8(),cashTarget=targets[4]||0;if(cashTarget<cashMin)breaches.push(`cash target ${cashTarget.toFixed(1)}% < ${cashMin.toFixed(1)}% minimum`);if(status){status.className=`outline-status ${breaches.length?'red':'green'}`;status.textContent=breaches.length?`${breaches.length} constraint${breaches.length===1?'':'s'} fail`:'12 / 12 valid'}if(breaches.length)toast('Optimisation completed with constraint exceptions',breaches.join(' · '),'warn')}

function createExpectationV8(){openDrawer({eyebrow:'CASH CONTROL · EXPECTED MOVEMENT',title:'New expected cash movement',subtitle:'Projection only. This does not post to the ledger.',body:`<form id="expectationFormV8"><section class="detail-section"><div class="detail-grid"><label class="detail-field"><span>Cash account</span><select id="expectAccountV8">${cashAccounts.map(a=>`<option value="${a.id}">${a.id} · ${escapeHtmlV8(a.portfolio)} · ${a.currency}</option>`).join('')}</select></label><label class="detail-field"><span>Direction</span><select id="expectDirectionV8"><option>Inflow</option><option>Outflow</option></select></label><label class="detail-field"><span>Amount</span><input id="expectAmountV8" type="number" min="0.01" step="0.01" required></label><label class="detail-field"><span>Expected date</span><input id="expectDateV8" type="date" value="2026-08-29" required></label><label class="detail-field"><span>Purpose</span><input id="expectPurposeV8" placeholder="Dividend, subscription, settlement..." required></label></div></section><div class="form-actions"><button class="btn secondary" type="button" onclick="closeDrawer()">Cancel</button><button class="btn primary" type="submit">Create expectation</button></div></form>`});setTimeout(()=>document.getElementById('expectationFormV8')?.addEventListener('submit',e=>{e.preventDefault();const amount=Number(document.getElementById('expectAmountV8').value);if(!(amount>0))return toast('Amount required','Enter a positive expected amount.','error');const acct=document.getElementById('expectAccountV8').value,dir=document.getElementById('expectDirectionV8').value,purpose=document.getElementById('expectPurposeV8').value.trim();closeDrawer();navigate('cash');switchCashTab('expectations');toast('Expected movement created',`${dir} ${amount.toLocaleString()} linked to ${acct} for ${purpose||'controlled purpose'}.`) }),0)}
function savePortfolioViewV8(){const config={search:document.getElementById('portfolioSearch')?.value||'',at:new Date().toISOString()};try{localStorage.setItem('matanho-portfolio-view-v8',JSON.stringify(config))}catch(e){}toast('View saved','Current portfolio search and workspace layout were saved to this browser.')}
function refreshScreeningV8(){document.querySelectorAll('#page-onboarding [data-onboarding-row]').forEach((r,i)=>{r.dataset.screenedAt=new Date().toISOString();if(i===0)r.classList.add('recently-updated')});toast('Screening refreshed',`Sanctions, PEP and identity controls refreshed at ${new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}.`)}
function runReconciliationV8(button){const before=document.querySelector('#page-operations .recon-summary strong');if(button){button.disabled=true;button.dataset.originalText=button.textContent;button.textContent='Running…'}setTimeout(()=>{if(before&&/\d/.test(before.textContent))before.textContent=before.textContent;if(button){button.disabled=false;button.textContent=button.dataset.originalText||'Run reconciliation'}toast('Reconciliation complete','Latest internal and external records were matched. Open exceptions remain in the workbench with owners and evidence.')},650)}


function promoteScenarioOrdersV9(){
 if(!hasPermission('orders.create'))return toast('Permission denied',`${roleLabels[state.role]} cannot promote model trades into the order workflow.`,'error');
 const sc=portfolioScenariosV8.find(x=>x.id===activeScenarioIdV8); if(!sc)return toast('Scenario required','Select or create a scenario before raising orders.','error');
 const existing=orders.filter(o=>o.sourceScenario===sc.id);
 if(existing.length){navigate('orders');renderOrders();return toast('Scenario already staged',`${existing.length} order${existing.length===1?'':'s'} from ${sc.name} are already in Order Management.`,'warn')}
 const stamp=new Date(), hh=String(stamp.getHours()).padStart(2,'0'), mm=String(stamp.getMinutes()).padStart(2,'0');
 const suffix=String(Date.now()).slice(-4);
 const templates=[
  {security:'DLTA.ZW',name:'Delta Corporation Limited',market:'ZSE',side:'Buy',qty:'77,333',limit:'ZWG 31.94',notional:'ZWG 2.47M',broker:'Imara Edwards',decisionPrice:'ZWG 31.94',risk:'Issuer headroom review'},
  {security:'INN.ZW',name:'Innscor Africa Limited',market:'ZSE',side:'Buy',qty:'207,609',limit:'ZWG 18.40',notional:'ZWG 3.82M',broker:'FBC Securities',decisionPrice:'ZWG 18.31',risk:'Within'},
  {security:'T-BILL-91D',name:'91-day Treasury Bill',market:'OTC',side:'Sell',qty:'530,000',limit:'9.10%',notional:'US$ 530k',broker:'OTC',decisionPrice:'9.10%',risk:'Duration reduction'},
  {security:'ZIM.VX',name:'Zimplats Holdings',market:'VFEX',side:'Buy',qty:'75,109',limit:'US$ 2.29',notional:'US$ 172k',broker:'IH Securities',decisionPrice:'US$ 2.27',risk:'Liquidity review'}
 ];
 templates.reverse().forEach((t,i)=>orders.unshift({id:`SCN-${suffix}-${String(templates.length-i).padStart(2,'0')}`,time:`${hh}:${mm}`,...t,portfolio:sc.portfolio,status:'Draft',owner:roleLabels[state.role],makerRole:state.role,fill:0,filledQty:'0',avg:'—',control:'Pending',approval:'Not submitted',route:'Not routed',settlement:t.market==='ZSE'?'T+3 · pending':t.market==='VFEX'?'T+2 · pending':'Same day · pending',tif:'Day',urgency:'Normal',allocation:'Single portfolio',age:'Just now',slippage:'—',sourceScenario:sc.id,scenarioName:sc.name}));
 renderOrders(); renderPretrade(); navigate('orders');
 toast('Scenario promoted to Order Management',`${templates.length} market instructions from ${sc.name} were created as Draft orders. Cash deployment remains an internal allocation and no broker instruction was sent.`)
}
function createPortfolioV9(){
 if(!hasPermission('portfolio.view'))return toast('Permission denied','Portfolio access is required.','error');
 openDrawer({eyebrow:'PORTFOLIO MASTER · CONTROLLED SETUP',title:'Create portfolio',subtitle:'Create a draft portfolio master. It remains non-tradable until mandate, risk, accounting and cash controls are complete.',body:`<form id="createPortfolioFormV9"><section class="detail-section"><div class="detail-grid"><label class="detail-field"><span>Portfolio name</span><input id="portfolioNameV9" placeholder="e.g. Alpha Balanced Mandate" required></label><label class="detail-field"><span>Portfolio type</span><select id="portfolioTypeV9"><option>Segregated mandate</option><option>Balanced Fund</option><option>Equity Fund</option><option>Money Market</option><option>Absolute Return</option></select></label><label class="detail-field"><span>Base currency</span><select id="portfolioCcyV9"><option>USD</option><option>ZWG</option></select></label><label class="detail-field"><span>Portfolio manager</span><select id="portfolioManagerV9"><option>T. Moyo</option><option>R. Dube</option><option>K. Moyo</option><option>S. Ncube</option></select></label><label class="detail-field"><span>Benchmark</span><input id="portfolioBenchmarkV9" placeholder="Approved benchmark / composite"></label><label class="detail-field"><span>Mandate reference</span><input id="portfolioMandateV9" placeholder="MAN-2026-..."></label></div></section><section class="detail-section"><h3>Activation gates</h3><div class="control-checklist compact"><div><span>1</span><p><strong>Mandate & benchmark</strong><small>Must be approved before trading.</small></p></div><div><span>2</span><p><strong>Risk limits</strong><small>Hard and soft controls required.</small></p></div><div><span>3</span><p><strong>Cash & custody</strong><small>Controlled accounts and mappings required.</small></p></div><div><span>4</span><p><strong>Accounting & reporting</strong><small>Basis, fees and reporting policy required.</small></p></div></div></section><div class="form-actions"><button type="button" class="btn secondary" onclick="closeDrawer()">Cancel</button><button type="submit" class="btn primary">Create draft portfolio</button></div></form>`});
 setTimeout(()=>document.getElementById('createPortfolioFormV9')?.addEventListener('submit',e=>{e.preventDefault();const name=document.getElementById('portfolioNameV9').value.trim();if(!name)return;if(portfolios.some(p=>p.name.toLowerCase()===name.toLowerCase()))return toast('Portfolio already exists','Choose a unique portfolio name.','error');const ccy=document.getElementById('portfolioCcyV9').value;portfolios.push({name,type:document.getElementById('portfolioTypeV9').value,ccy,aum:ccy==='USD'?'US$ 0.00':'ZWG 0.00',cash:'0.0%',ret:'—',bm:'—',risk:'Setup',manager:document.getElementById('portfolioManagerV9').value});renderPortfolios();closeDrawer();navigate('portfolios');toast('Draft portfolio created',`${name} was added to the portfolio master in Setup state. Complete mandate, risk, cash and accounting gates before activation.`)}),0)
}
function openPortfolioFiltersV9(){
 openDrawer({eyebrow:'WHOLE PORTFOLIO · FILTERS',title:'Portfolio filters',subtitle:'Apply the working view without changing source data.',body:`<form id="portfolioFilterFormV9"><section class="detail-section"><div class="detail-grid"><label class="detail-field"><span>Search</span><input id="portfolioFilterSearchV9" value="${escapeHtmlV8(document.getElementById('portfolioSearch')?.value||'')}"></label><label class="detail-field"><span>Risk state</span><select id="portfolioFilterRiskV9"><option value="all">All states</option><option>Within</option><option>Amber</option><option>Setup</option></select></label><label class="detail-field"><span>Manager</span><select id="portfolioFilterManagerV9"><option value="all">All managers</option>${[...new Set(portfolios.map(p=>p.manager))].map(x=>`<option>${escapeHtmlV8(x)}</option>`).join('')}</select></label><label class="detail-field"><span>Currency</span><select id="portfolioFilterCcyV9"><option value="all">All currencies</option><option>USD</option><option>ZWG</option></select></label></div></section><div class="form-actions"><button class="btn secondary" type="button" id="clearPortfolioFiltersV9">Clear</button><button class="btn primary" type="submit">Apply filters</button></div></form>`});
 setTimeout(()=>{const f=document.getElementById('portfolioFilterFormV9');document.getElementById('clearPortfolioFiltersV9')?.addEventListener('click',()=>{document.getElementById('portfolioFilterSearchV9').value='';document.getElementById('portfolioFilterRiskV9').value='all';document.getElementById('portfolioFilterManagerV9').value='all';document.getElementById('portfolioFilterCcyV9').value='all'});f?.addEventListener('submit',e=>{e.preventDefault();const q=document.getElementById('portfolioFilterSearchV9').value.trim().toLowerCase(),risk=document.getElementById('portfolioFilterRiskV9').value,mgr=document.getElementById('portfolioFilterManagerV9').value,ccy=document.getElementById('portfolioFilterCcyV9').value;document.querySelectorAll('#portfolioRows tr').forEach((row,i)=>{const p=portfolios[i];if(!p)return;row.style.display=(!q||`${p.name} ${p.type} ${p.manager}`.toLowerCase().includes(q))&&(risk==='all'||p.risk===risk)&&(mgr==='all'||p.manager===mgr)&&(ccy==='all'||p.ccy===ccy)?'':'none'});const s=document.getElementById('portfolioSearch');if(s)s.value=document.getElementById('portfolioFilterSearchV9').value;closeDrawer();toast('Portfolio filters applied','The working portfolio view now reflects the selected filters.')})},0)
}
function startNavRunV9(){
 const tag=document.querySelector('#page-valuation .nav-run .tag'); if(tag){tag.className='tag blue';tag.textContent='Pre-check running'}
 const step=document.querySelector('#page-valuation .nav-steps .warning'); if(step)step.classList.add('pulse-attention');
 setTimeout(()=>{if(tag){tag.className='tag amber';tag.textContent='Blocked · 1 price exception'}openControlDrawer('NAV run control','The run reached the price-control gate and stopped with an explicit blocker.',`<section class="detail-section"><h3>Run result</h3><div class="close-blockers"><div class="pass"><span>✓</span><p><strong>Positions</strong><small>Reconciled and frozen for the run.</small></p></div><div class="pass"><span>✓</span><p><strong>Cash</strong><small>Reconciled to committed external evidence.</small></p></div><div class="fail"><span>!</span><p><strong>Price control</strong><small>OMU.ZW stale price requires independent review.</small></p></div></div></section><div class="form-actions"><button class="btn primary" type="button" onclick="closeDrawer();handleAction('price-exceptions')">Review price exception</button></div>`);},450);
}

const baseApproveOrderV9=approveOrder;approveOrder=function(id){const o=orders.find(x=>x.id===id);if(o&&accessPolicyV8.orderApproval==='independent'&&o.makerRole&&o.makerRole===state.role)return toast('Maker-checker conflict','The role that created this order cannot approve the same order while independent approval is enforced. Switch to an authorised independent approver.','error');return baseApproveOrderV9(id)};window.approveOrder=approveOrder;
const baseHandleActionV8=handleAction;handleAction=function(action){
 if(action==='scenario-howto')return openScenarioHowToV8();
 if(action==='new-scenario')return openNewScenarioV8();
 if(action==='raise-proposed-orders')return promoteScenarioOrdersV9();
 if(action==='create-portfolio')return createPortfolioV9();
 if(action==='open-portfolio-filters')return openPortfolioFiltersV9();
 if(action==='start-nav-run')return startNavRunV9();
 if(action==='save-scenario')return saveActiveScenarioV8();
 if(action==='compare-scenarios')return compareScenariosV8();
 if(action==='new-role')return openNewRoleBuilderV8();
 if(action==='add-user')return addUserV8();
 if(action==='run-sod-scan'){const n=renderSodV8();return toast('SoD scan complete',n?`${n} finding${n===1?'':'s'} require review.`:'No blocking conflicts detected.');}
 if(action==='save-rbac-policy')return saveRbacPolicyV8();
 if(action==='reset-rbac')return resetRbacV8();
 if(action==='preview-current-role'){applyRBAC(true);return navigate(platformSettingsV8.startPage||'command')}
 if(action==='save-platform-settings')return saveSettingsV8();
 if(action==='reset-platform-settings')return resetSettingsV8();
 if(action==='save-view')return savePortfolioViewV8();
 if(action==='refresh-screening')return refreshScreeningV8();
 if(action==='new-expectation')return createExpectationV8();
 if(action==='run-reconciliation')return runReconciliationV8(document.querySelector('[data-action="run-reconciliation"]'));
 return baseHandleActionV8(action)
};

const baseOpenQuickOrderPanelV8=openQuickOrderPanel;openQuickOrderPanel=function(){baseOpenQuickOrderPanelV8();const panel=document.getElementById('marketTradePanel');if(panel?.hidden)return;const body=panel.querySelector('.quick-order-body-v8');if(body)body.scrollTop=0;const type=document.getElementById('quickOrderType'),portfolio=document.getElementById('quickOrderPortfolio');if(type){type.value=platformSettingsV8.defaultOrderType;document.getElementById('quickLimitPrice').disabled=type.value==='Market'}if(portfolio&&[...portfolio.options].some(o=>o.text===platformSettingsV8.defaultPortfolio))portfolio.value=platformSettingsV8.defaultPortfolio;recalcQuickOrder();requestAnimationFrame(()=>document.querySelector('#quickTradeSide [data-side].active')?.focus({preventScroll:true}))};
const baseCloseQuickOrderPanelV8=closeQuickOrderPanel;closeQuickOrderPanel=function(restoreFocus=true){baseCloseQuickOrderPanelV8(restoreFocus);const body=document.querySelector('#marketTradePanel .quick-order-body-v8');if(body)body.scrollTop=0};

function initWorkflowV8(){localLoadV8();renderRoleSwitcherV8();renderRbacMatrix();renderRbacUsersV8();renderRbacPolicyV8();renderSettingsV8();renderScenarioLibraryV8();document.getElementById('scenarioLibrarySelect')?.addEventListener('change',e=>loadScenarioV8(e.target.value));['scenarioPortfolioSelect','scenarioObjectiveSelect','scenarioTeInput','scenarioCashInput','scenarioTurnoverInput'].forEach(id=>document.getElementById(id)?.addEventListener('change',()=>{const sc=portfolioScenariosV8.find(x=>x.id===activeScenarioIdV8);if(sc){if(id==='scenarioPortfolioSelect')document.getElementById('scenarioContextPortfolio').textContent=document.getElementById(id).value;if(id==='scenarioObjectiveSelect'||id==='scenarioTeInput')document.getElementById('scenarioContextObjective').textContent=`${document.getElementById('scenarioObjectiveSelect').selectedOptions[0].text} / ${Number(document.getElementById('scenarioTeInput').value).toFixed(1)}% TE`}}));document.querySelectorAll('[data-scenario-target]').forEach(i=>i.addEventListener('input',recalcScenarioTargetsV8));document.getElementById('normalizeScenarioTargets')?.addEventListener('click',normalizeScenarioTargetsV8);applySettingsV8();applyRBAC(false)}
window.loadScenarioV8=loadScenarioV8;window.openScenarioHowToV8=openScenarioHowToV8;window.saveRbacPolicyV8=saveRbacPolicyV8;window.saveSettingsV8=saveSettingsV8;
document.addEventListener('DOMContentLoaded',initWorkflowV8);

